CREATE TYPE "LeadType" AS ENUM ('BUYER', 'SELLER');
CREATE TYPE "Priority" AS ENUM ('LOW', 'NORMAL', 'HIGH');
CREATE TABLE "AdminUser" ("id" TEXT PRIMARY KEY, "email" TEXT NOT NULL UNIQUE, "passwordHash" TEXT NOT NULL, "twoFactorKey" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "Session" ("id" TEXT PRIMARY KEY, "tokenHash" TEXT NOT NULL UNIQUE, "userId" TEXT NOT NULL REFERENCES "AdminUser"("id") ON DELETE CASCADE, "expiresAt" TIMESTAMP(3) NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "Session_expiresAt_idx" ON "Session"("expiresAt");
CREATE TABLE "PasswordResetToken" ("id" TEXT PRIMARY KEY, "tokenHash" TEXT NOT NULL UNIQUE, "userId" TEXT NOT NULL REFERENCES "AdminUser"("id") ON DELETE CASCADE, "expiresAt" TIMESTAMP(3) NOT NULL, "usedAt" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "PasswordResetToken_expiresAt_idx" ON "PasswordResetToken"("expiresAt");
CREATE TABLE "Lead" ("id" TEXT PRIMARY KEY, "idempotencyKey" TEXT NOT NULL UNIQUE, "type" "LeadType" NOT NULL, "firstName" TEXT NOT NULL, "lastName" TEXT NOT NULL, "email" TEXT NOT NULL, "phone" TEXT NOT NULL, "preferredContact" TEXT NOT NULL, "bestTime" TEXT, "language" TEXT NOT NULL, "source" TEXT, "status" TEXT NOT NULL DEFAULT 'New Inquiry', "priority" "Priority" NOT NULL DEFAULT 'NORMAL', "details" JSONB NOT NULL, "linkedBuyerNeed" JSONB, "consentPrivacy" BOOLEAN NOT NULL, "consentCallsTexts" BOOLEAN NOT NULL DEFAULT false, "followUpAt" TIMESTAMP(3), "archivedAt" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL);
CREATE INDEX "Lead_type_status_idx" ON "Lead"("type", "status"); CREATE INDEX "Lead_createdAt_idx" ON "Lead"("createdAt"); CREATE INDEX "Lead_followUpAt_idx" ON "Lead"("followUpAt");
CREATE TABLE "LeadActivity" ("id" TEXT PRIMARY KEY, "leadId" TEXT NOT NULL REFERENCES "Lead"("id") ON DELETE CASCADE, "action" TEXT NOT NULL, "detail" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP); CREATE INDEX "LeadActivity_leadId_createdAt_idx" ON "LeadActivity"("leadId", "createdAt");
CREATE TABLE "LeadNote" ("id" TEXT PRIMARY KEY, "leadId" TEXT NOT NULL REFERENCES "Lead"("id") ON DELETE CASCADE, "body" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "FollowUpTask" ("id" TEXT PRIMARY KEY, "leadId" TEXT NOT NULL REFERENCES "Lead"("id") ON DELETE CASCADE, "title" TEXT NOT NULL, "dueAt" TIMESTAMP(3), "completedAt" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "EmailEvent" ("id" TEXT PRIMARY KEY, "leadId" TEXT NOT NULL REFERENCES "Lead"("id") ON DELETE CASCADE, "kind" TEXT NOT NULL, "recipient" TEXT NOT NULL, "subject" TEXT NOT NULL, "status" TEXT NOT NULL, "providerId" TEXT, "error" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "LeadFile" ("id" TEXT PRIMARY KEY, "leadId" TEXT NOT NULL REFERENCES "Lead"("id") ON DELETE CASCADE, "url" TEXT NOT NULL, "publicId" TEXT, "name" TEXT NOT NULL, "mimeType" TEXT NOT NULL, "size" INTEGER NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "SiteContent" ("id" TEXT PRIMARY KEY DEFAULT 'primary', "content" JSONB NOT NULL, "updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "Testimonial" ("id" TEXT PRIMARY KEY, "quote" TEXT NOT NULL, "name" TEXT NOT NULL, "context" TEXT, "published" BOOLEAN NOT NULL DEFAULT false, "sortOrder" INTEGER NOT NULL DEFAULT 0, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL);
